import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import type { MetaConn, QueryOutcome } from '../src/conn.ts'

/** Loads a golden fixture generated by scripts/generate-fixtures.php */
export function loadFixture<T>(name: string): T {
  const path = fileURLToPath(new URL(`./fixtures/${name}`, import.meta.url))
  return JSON.parse(readFileSync(path, 'utf8')) as T
}

export interface Recorded {
  kind: 'query' | 'selectDb' | 'multi'
  sql: string
}

/**
 * A scriptable MetaConn: `answer` returns rows (or an error) for each statement, and every call is
 * recorded the way the PHP fixture generator records phpMyAdmin's (query / selectDb / multi).
 */
export class FakeConn implements MetaConn {
  readonly log: Recorded[] = []
  lastError = ''
  lastErrno = 0
  answer: (sql: string) => QueryOutcome | { error: string; errno: number }
  selectDbAnswer: (db: string) => boolean

  constructor(
    answer: (sql: string) => QueryOutcome | { error: string; errno: number } = () => ok(),
    selectDbAnswer: (db: string) => boolean = () => true,
  ) {
    this.answer = answer
    this.selectDbAnswer = selectDbAnswer
  }

  #run(sql: string): QueryOutcome | false {
    const r = this.answer(sql)
    if ('error' in r) {
      this.lastError = r.error
      this.lastErrno = r.errno
      return false
    }
    this.lastError = ''
    this.lastErrno = 0
    return r
  }

  async query(sql: string): Promise<QueryOutcome> {
    this.log.push({ kind: 'query', sql })
    const r = this.#run(sql)
    if (r === false) throw new Error(this.lastError)
    return r
  }

  async tryQuery(sql: string): Promise<QueryOutcome | false> {
    this.log.push({ kind: 'query', sql })
    return this.#run(sql)
  }

  async selectDb(db: string): Promise<boolean> {
    this.log.push({ kind: 'selectDb', sql: db })
    return this.selectDbAnswer(db)
  }

  async tryMultiQuery(sql: string): Promise<boolean> {
    this.log.push({ kind: 'multi', sql })
    return this.#run(sql) !== false
  }
}

export function ok(rows: Array<Record<string, string | null>> = [], fields?: string[]): QueryOutcome {
  return { fields: fields ?? Object.keys(rows[0] ?? {}), rows, affectedRows: 0 }
}
